146	// strictObject decodes raw as a JSON object whose keys must all be allowed,
147	// rejecting syntax errors, trailing data, duplicates, non-objects and
148	// unknown keys. It returns the raw members for typed decoding.
149	func strictObject(raw []byte, allowed []string, what string) (map[string]json.RawMessage, error) {
150		trimmed := bytes.TrimSpace(raw)
151		if len(trimmed) == 0 || trimmed[0] != '{' {
152			return nil, invalidf("%s must be a JSON object", what)
153		}
154		var members map[string]json.RawMessage
155		if err := json.Unmarshal(trimmed, &members); err != nil {
156			// Unmarshal also rejects trailing data after the top-level value.
157			return nil, invalidf("%s is not valid JSON: %v", what, err)
158		}
159		allowedSet := make(map[string]bool, len(allowed))
160		for _, k := range allowed {
161			allowedSet[k] = true
162		}
163		for key := range members {
164			if !allowedSet[key] {
165				return nil, invalidf("%s has unknown field %q", what, key)
166			}
167		}
168		if err := rejectDuplicateKeys(trimmed, what); err != nil {
169			return nil, err
170		}
171		return members, nil
172	}
