174	// rejectDuplicateKeys walks the JSON token stream rejecting any object that
175	// names the same key twice; encoding/json silently keeps the last value.
176	func rejectDuplicateKeys(raw []byte, what string) error {
177		dec := json.NewDecoder(bytes.NewReader(raw))
178		dec.UseNumber()
179		var walk func() error
180		walk = func() error {
181			tok, err := dec.Token()
182			if err != nil {
183				return invalidf("%s is not valid JSON: %v", what, err)
184			}
185			delim, ok := tok.(json.Delim)
186			if !ok {
187				return nil // scalar
188			}
189			switch delim {
190			case '{':
191				seen := make(map[string]bool)
192				for dec.More() {
193					keyTok, err := dec.Token()
194					if err != nil {
195						return invalidf("%s is not valid JSON: %v", what, err)
196					}
197					key := keyTok.(string)
198					if seen[key] {
199						return invalidf("%s contains duplicate field %q", what, key)
200					}
201					seen[key] = true
202					if err := walk(); err != nil {
203						return err
204					}
205				}
206				if _, err := dec.Token(); err != nil { // closing brace
207					return invalidf("%s is not valid JSON: %v", what, err)
208				}
209			case '[':
210				for dec.More() {
211					if err := walk(); err != nil {
212						return err
213					}
214				}
215				if _, err := dec.Token(); err != nil { // closing bracket
216					return invalidf("%s is not valid JSON: %v", what, err)
217				}
218			}
219			return nil
220		}
221		return walk()
222	}
