591	// ---- canonical JSON for persistence --------------------------------------
592	
593	func (d *canonicalDefinition) toPersist() persistDefinition {
594		out := persistDefinition{
595			Modulus:     fmt.Sprintf("%d", d.modulus),
596			Constraints: make([]persistConstraint, 0, len(d.constraints)),
597		}
598		combo := func(terms []parsedTerm) []persistTerm {
599			tt := make([]persistTerm, 0, len(terms))
600			for _, t := range terms {
601				tt = append(tt, persistTerm{Wire: t.wire, Coeff: fmt.Sprintf("%d", t.value)})
602			}
603			return tt
604		}
605		for _, con := range d.constraints {
606			out.Constraints = append(out.Constraints, persistConstraint{
607				A: combo(con.a), B: combo(con.b), C: combo(con.c),
608			})
609		}
610		return out
611	}
