81	// ErrNotFrozen. A version whose counts were registered but which never had a
82	// definition imported yields ErrDefinitionMissing. Repeated compilation of
83	// the same version is idempotent and returns the identical artifact; other
84	// versions' artifacts are unaffected.
85	func (s *Store) CompileCircuit(name string, version int) (Artifact, error) {
86		if err := validateCircuitKey(name, version); err != nil {
87			return Artifact{}, err
88		}
89		var result Artifact
90		err := s.withLock(func() (bool, error) {
91			circuit := findCircuit(s.data.Circuits, name, version)
92			if circuit == nil {
93				return false, notFoundf("circuit %q version %d does not exist", name, version)
94			}
95			if !circuit.Frozen {
96				return false, notFrozenf("circuit %q version %d must be frozen before compilation", name, version)
97			}
98			if existing := findArtifact(s.data.Artifacts, name, version); existing != nil {
99				result = artifactFromPersist(*existing)
100				return false, nil
101			}
102			if circuit.Definition == nil {
103				return false, definitionMissingf("circuit %q version %d has only registered counts and no constraint definition; import one before freezing",
104					name, version)
105			}
106			parsed, perr := definitionFromPersist(*circuit.Definition, circuit.PublicInputs, circuit.PrivateInputs)
107			if perr != nil {
108				return false, corruptf("stored definition for %q v%d is unreadable: %v", name, version, perr)
109			}
110			if !parsed.compatibleWith(circuit.Constraints, circuit.PublicInputs, circuit.PrivateInputs) {
111				return false, corruptf("stored definition for %q v%d no longer matches its declared counts", name, version)
112			}
113			record := persistArtifact{
