118				Hash:        artifactHash(name, version, parsed),
119			}
120			s.data.Artifacts = append(s.data.Artifacts, record)
121			result = artifactFromPersist(record)
122			return true, nil
123		})
124		return result, err
125	}
126	
127	// GetArtifact returns the compiled artifact for one version. A version
128	// without one yields ErrArtifactMissing, and an unknown version ErrNotFound.
129	func (s *Store) GetArtifact(name string, version int) (Artifact, error) {
130		if err := validateCircuitKey(name, version); err != nil {
131			return Artifact{}, err
132		}
133		var result Artifact
134		err := s.withLockRead(func() error {
135			circuit := findCircuit(s.data.Circuits, name, version)
136			if circuit == nil {
137				return notFoundf("circuit %q version %d does not exist", name, version)
138			}
139			existing := findArtifact(s.data.Artifacts, name, version)
140			if existing == nil {
141				return artifactMissingf("circuit %q version %d has no compiled artifact", name, version)
142			}
143			result = artifactFromPersist(*existing)
144			return nil
145		})
146		return result, err
147	}
148	
149	// CheckInput tests one input assignment against the named version's
150	// compiled artifact. hash must equal that artifact's hash, binding the check
151	// to an explicit compilation result.
152	//
153	// Gating errors are reported distinctly: unknown version ErrNotFound,
154	// unfrozen version ErrNotFrozen, no compiled artifact ErrArtifactMissing and
