// validatePersistDefinition re-validates a stored definition from its raw
// JSON through the same strict grammar used at import: every required field
// must be present with its proper type (modulus as a string, constraints as
// an array, a/b/c arrays on every constraint, integer wire and string coeff
// on every term) and nulls are rejected outright. The typed envelope decode
// alone cannot make these distinctions: a missing or null array decodes like
// a legitimate empty one and a missing or null wire like the constant wire
// 0. On top of the grammar the definition must still match the version's
// declared counts: prime modulus, in-range wires and an exact constraint
// count.
func validatePersistDefinition(name string, version, constraints, public, private int, raw json.RawMessage) error {
    trimmed := strings.TrimSpace(string(raw))
    if trimmed == "" || trimmed == "null" {
        return fmt.Errorf("circuit %q v%d has a corrupt constraint definition: the definition must be an object", name, version)
    }
    if _, err := parseDefinitionJSON(raw, public, private, constraints); err != nil {
        return fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
    }
    return nil
}
