	}
	if r := call("circuit-list", "--dir", dir); r.code != 0 || !strings.Contains(r.out, "transfer") {
		t.Fatalf("circuit list: %+v", r)
	}
	if r := call("setup-get", "--dir", dir, "--name", "transfer", "--version", "1"); r.code != 0 || !strings.Contains(r.out, "present=true") {
